    fn missing_as_ref<M>(missing: &Self::Missing<M>) -> Self::Missing<&M>;
    /// Map the broad payload inside a `Missing` payload.
    fn map_missing<M, N>(missing: Self::Missing<M>, map: impl FnOnce(M) -> N) -> Self::Missing<N>;
