/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_base_content_item<'tree>(
    node: BaseContentItemNode<'tree>,
) -> BaseContentItemChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    let content = {
        let (leading_extras, __placed) = __cur.fixed(
            ChoiceAt {
                shape: &SHAPE_39,
                select: choice_39,
            },
            &Cont::NIL,
        );
        let slot = match __placed {
            Some(__placed) => match __placed {
                ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                    ChoicePick39::A0(node) => {
                        BaseContentItemChoice::UnderlineBegin(UnderlineBeginNode(node))
                    }
                    ChoicePick39::A1(node) => {
                        BaseContentItemChoice::UnderlineEnd(UnderlineEndNode(node))
                    }
                    ChoicePick39::A2(node) => {
                        BaseContentItemChoice::PauseToken(PauseTokenNode(node))
                    }
                    ChoicePick39::A3(node) => BaseContentItemChoice::WordWithOptionalAnnotations(
                        WordWithOptionalAnnotationsNode(node),
                    ),
                    ChoicePick39::A4(node) => {
                        BaseContentItemChoice::NonwordWithOptionalAnnotations(
                            NonwordWithOptionalAnnotationsNode(node),
                        )
                    }
                    ChoicePick39::A5(node) => {
                        BaseContentItemChoice::OtherSpokenEvent(OtherSpokenEventNode(node))
                    }
                    ChoicePick39::A6(node) => {
                        BaseContentItemChoice::LongFeature(LongFeatureNode(node))
                    }
                    ChoicePick39::A7(node) => BaseContentItemChoice::Nonvocal(NonvocalNode(node)),
                    ChoicePick39::A8(node) => BaseContentItemChoice::Freecode(FreecodeNode(node)),
                    ChoicePick39::A9(node) => BaseContentItemChoice::Bullet(BulletNode(node)),
                }),
                ChoicePlaced::Missing(node) => NodeSlot::Missing(node),
                ChoicePlaced::Error(node) => NodeSlot::Error(node),
            },
            None => NodeSlot::Absent(NoChild),
        };
        Positioned::new(leading_extras, slot)
    };
    let Leftovers {
        trailing_extras,
        unexpected,
    } = __cur.finish();
    BaseContentItemChildren {
        content,
        trailing_extras,
        unexpected,
    }
}
impl<'tree> Extract<'tree> for BaseContentItemNode<'tree> {
    type Children<K: KindProof> = BaseContentItemChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<BaseContentItemChildren<'tree>, K::Refusal> {
        K::admit(evidence, self.0).map(|__raw| extract_base_content_item(Self(__raw)))
    }
    fn extract_broad(self) -> BaseContentItemChildren<'tree> {
        extract_base_content_item(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<BaseContentItemChildren<'tree>, AdmittedRefusal> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
