/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_content_item<'tree>(node: ContentItemNode<'tree>) -> ContentItemChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    let content = {
        let (leading_extras, __placed) = __cur.fixed(
            ChoiceAt {
                shape: &SHAPE_87,
                select: choice_87,
            },
            &Cont::NIL,
        );
        let slot = match __placed {
            Some(__placed) => match __placed {
                ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                    ChoicePick87::A0(node) => {
                        ContentItemChoice::BaseContentItem(BaseContentItemNode(node))
                    }
                    ChoicePick87::A1(node) => {
                        ContentItemChoice::GroupWithAnnotations(GroupWithAnnotationsNode(node))
                    }
                    ChoicePick87::A2(node) => ContentItemChoice::QuotationWithOptionalAnnotations(
                        QuotationWithOptionalAnnotationsNode(node),
                    ),
                    ChoicePick87::A3(node) => {
                        ContentItemChoice::IllegalCurlyQuote(IllegalCurlyQuoteNode(node))
                    }
                    ChoicePick87::A4(node) => {
                        ContentItemChoice::MainPhoGroup(MainPhoGroupNode(node))
                    }
                    ChoicePick87::A5(node) => {
                        ContentItemChoice::MainSinGroup(MainSinGroupNode(node))
                    }
                    ChoicePick87::A6(node, tag) => ContentItemChoice::CaNoBreakLinker(match tag {
                        KindTag1::CaNoBreakLinkerNode => {
                            ContentItemCaNoBreakLinkerChoice::CaNoBreakLinker(CaNoBreakLinkerNode(
                                node,
                            ))
                        }
                        KindTag1::CaTechnicalBreakLinkerNode => {
                            ContentItemCaNoBreakLinkerChoice::CaTechnicalBreakLinker(
                                CaTechnicalBreakLinkerNode(node),
                            )
                        }
                        KindTag1::LinkerLazyOverlapNode => {
                            ContentItemCaNoBreakLinkerChoice::LinkerLazyOverlap(
                                LinkerLazyOverlapNode(node),
                            )
                        }
                        KindTag1::LinkerQuickUptakeNode => {
                            ContentItemCaNoBreakLinkerChoice::LinkerQuickUptake(
                                LinkerQuickUptakeNode(node),
                            )
                        }
                        KindTag1::LinkerQuickUptakeOverlapNode => {
                            ContentItemCaNoBreakLinkerChoice::LinkerQuickUptakeOverlap(
                                LinkerQuickUptakeOverlapNode(node),
                            )
                        }
                        KindTag1::LinkerQuotationFollowsNode => {
                            ContentItemCaNoBreakLinkerChoice::LinkerQuotationFollows(
                                LinkerQuotationFollowsNode(node),
                            )
                        }
                        KindTag1::LinkerSelfCompletionNode => {
                            ContentItemCaNoBreakLinkerChoice::LinkerSelfCompletion(
                                LinkerSelfCompletionNode(node),
                            )
                        }
                    }),
                }),
                ChoicePlaced::Missing(node) => NodeSlot::Missing(node),
                ChoicePlaced::Error(node) => NodeSlot::Error(node),
            },
            None => NodeSlot::Absent(NoChild),
        };
        Positioned::new(leading_extras, slot)
    };
    let Leftovers {
        trailing_extras,
        unexpected,
    } = __cur.finish();
    ContentItemChildren {
        content,
        trailing_extras,
        unexpected,
    }
}
impl<'tree> Extract<'tree> for ContentItemNode<'tree> {
    type Children<K: KindProof> = ContentItemChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<ContentItemChildren<'tree>, K::Refusal> {
        K::admit(evidence, self.0).map(|__raw| extract_content_item(Self(__raw)))
    }
    fn extract_broad(self) -> ContentItemChildren<'tree> {
        extract_content_item(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<ContentItemChildren<'tree>, AdmittedRefusal> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
