/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_free_text<'tree>(node: FreeTextNode<'tree>) -> FreeTextChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    {
        let child_0 = {
            let __c0 = __cur.tail(&SHAPES_11);
            let (leading_extras, __placed) = __cur.fixed(
                ChoiceAt {
                    shape: &SHAPE_118,
                    select: choice_118,
                },
                &__c0,
            );
            let slot = match __placed {
                Some(__placed) => match __placed {
                    ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                        ChoicePick118::A0(node) => {
                            FreeTextChild0Choice::RestOfLine(RestOfLineNode(node))
                        }
                        ChoicePick118::A1(node) => {
                            FreeTextChild0Choice::Continuation(ContinuationNode(node))
                        }
                    }),
                    ChoicePlaced::Missing(node) => NodeSlot::Missing(node),
                    ChoicePlaced::Error(node) => NodeSlot::Error(node),
                },
                None => NodeSlot::Absent(NoChild),
            };
            Positioned::new(leading_extras, slot)
        };
        let child_1 = {
            let (leading_extras, mut __walk) = __cur.repeat(&SHAPE_119, &Cont::NIL);
            let mut __items = Vec::with_capacity(__walk.capacity());
            while let Some((leading_extras, __placed, __c1)) = __walk.next(
                &mut __cur,
                ChoiceAt {
                    shape: &SHAPE_118,
                    select: choice_118,
                },
            ) {
                __items.push(Positioned::new(
                    leading_extras,
                    match __placed {
                        ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                            ChoicePick118::A0(node) => {
                                FreeTextChild1Choice::RestOfLine(RestOfLineNode(node))
                            }
                            ChoicePick118::A1(node) => {
                                FreeTextChild1Choice::Continuation(ContinuationNode(node))
                            }
                        }),
                        ChoicePlaced::Missing(node) => NodeSlot::Missing(node),
                        ChoicePlaced::Error(node) => NodeSlot::Error(node),
                    },
                ));
            }
            Positioned::new(leading_extras, __items)
        };
        let Leftovers {
            trailing_extras,
            unexpected,
        } = __cur.finish();
        FreeTextChildren {
            child_0,
            child_1,
            trailing_extras,
            unexpected,
        }
    }
}
