impl<'tree> Extract<'tree> for GHeaderNode<'tree> {
    type Children<K: KindProof> = GHeaderChildren<'tree, K>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<GHeaderChildren<'tree, K>, K::Refusal> {
        let __raw = K::admit(evidence, self.0)?;
        Ok({
            let __children = collect_children(__raw);
            let mut __cur = Cursor::new(&__children);
            {
                let child_0 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_132), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(GPrefixNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(KindMissing(GPrefixNode(node)))
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_1 = {
                    let __c0 = __cur.tail(&SHAPES_0);
                    let (leading_extras, __placed) = __cur.optional(Sequence(&SHAPE_42), &__c0);
                    let slot = match __placed {
                        Some(__placed) => Some(match __placed {
                            SequencePlaced::Value => NodeSlot::Present({
                                let child_0 = {
                                    let (leading_extras, __placed) =
                                        __cur.fixed(Terminal::of(&SHAPE_8), &Cont::NIL);
                                    let slot = match __placed {
                                        Some(__placed) => match __placed {
                                            TerminalPlaced::Present(node, ()) => {
                                                NodeSlot::Present(HeaderSepNode(node))
                                            }
                                            TerminalPlaced::Missing(node, ()) => NodeSlot::Missing(
                                                K::missing(KindMissing(HeaderSepNode(node)))?,
                                            ),
                                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                                        },
                                        None => NodeSlot::Absent(NoChild),
                                    };
                                    Positioned::new(leading_extras, slot)
                                };
                                let child_1 = {
                                    let (leading_extras, __placed) =
                                        __cur.fixed(Terminal::of(&SHAPE_10), &Cont::NIL);
                                    let slot = match __placed {
                                        Some(__placed) => match __placed {
                                            TerminalPlaced::Present(node, ()) => {
                                                NodeSlot::Present(FreeTextNode(node))
                                            }
                                            TerminalPlaced::Missing(node, ()) => NodeSlot::Missing(
                                                K::missing(KindMissing(FreeTextNode(node)))?,
                                            ),
                                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                                        },
                                        None => NodeSlot::Absent(NoChild),
                                    };
                                    Positioned::new(leading_extras, slot)
                                };
                                GHeaderChild1Children {
                                    child_0,
                                    child_1,
                                    trailing_extras: Vec::new(),
                                    unexpected: Vec::new(),
                                }
                            }),
                            SequencePlaced::Error(node) => NodeSlot::Error(node),
                        }),
                        None => None,
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_2 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_5), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(NewlineNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(KindMissing(NewlineNode(node)))
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let Leftovers {
                    trailing_extras,
                    unexpected,
                } = __cur.finish();
                GHeaderChildren {
                    child_0,
                    child_1,
                    child_2,
                    trailing_extras,
                    unexpected,
                }
            }
        })
    }
    fn extract_broad(self) -> GHeaderChildren<'tree> {
        extract_g_header(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<GHeaderChildren<'tree, KindAdmitted>, AdmittedRefusal> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
