/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_id_age<'tree>(node: IdAgeNode<'tree>) -> IdAgeChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    let content = {
        let (leading_extras, __placed) = __cur.fixed(
            ChoiceAt {
                shape: &SHAPE_167,
                select: choice_167,
            },
            &Cont::NIL,
        );
        let slot = match __placed {
            Some(__placed) => match __placed {
                ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                    ChoicePick167::A0(node) => IdAgeChoice::AgeFormat(AgeFormatNode(node)),
                    ChoicePick167::A1 => IdAgeChoice::TRNRNTRN(LeafText(__raw)),
                }),
                ChoicePlaced::Missing(node) => NodeSlot::Missing(node),
                ChoicePlaced::Error(node) => NodeSlot::Error(node),
            },
            None => NodeSlot::Absent(NoChild),
        };
        Positioned::new(leading_extras, slot)
    };
    let Leftovers {
        trailing_extras,
        unexpected,
    } = __cur.finish();
    IdAgeChildren {
        content,
        trailing_extras,
        unexpected,
    }
}
impl<'tree> Extract<'tree> for IdAgeNode<'tree> {
    type Children<K: KindProof> = IdAgeChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<IdAgeChildren<'tree>, K::Refusal> {
        K::admit(evidence, self.0).map(|__raw| extract_id_age(Self(__raw)))
    }
    fn extract_broad(self) -> IdAgeChildren<'tree> {
        extract_id_age(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<IdAgeChildren<'tree>, AdmittedRefusal> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
