/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_media_filename<'tree>(
    node: MediaFilenameNode<'tree>,
) -> MediaFilenameChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    let content = {
        let (leading_extras, __placed) = __cur.fixed(
            ChoiceAt {
                shape: &SHAPE_264,
                select: choice_264,
            },
            &Cont::NIL,
        );
        let slot = match __placed {
            Some(__placed) => match __placed {
                ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                    ChoicePick264::A0 => MediaFilenameChoice::DoubleQuote({
                        let child_0 = {
                            let (leading_extras, __placed) =
                                __cur.fixed(Terminal::of(&SHAPE_261), &Cont::NIL);
                            let slot = match __placed {
                                Some(__placed) => match __placed {
                                    TerminalPlaced::Present(node, ()) => {
                                        NodeSlot::Present(DoubleQuoteNode(node))
                                    }
                                    TerminalPlaced::Missing(node, ()) => {
                                        NodeSlot::Missing(KindMissing(DoubleQuoteNode(node)))
                                    }
                                    TerminalPlaced::Error(node) => NodeSlot::Error(node),
                                },
                                None => NodeSlot::Absent(NoChild),
                            };
                            Positioned::new(leading_extras, slot)
                        };
                        let child_1 = __cur.absorbed_leaf_span(__raw);
                        let child_2 = {
                            let (leading_extras, __placed) =
                                __cur.fixed(Terminal::of(&SHAPE_261), &Cont::NIL);
                            let slot = match __placed {
                                Some(__placed) => match __placed {
                                    TerminalPlaced::Present(node, ()) => {
                                        NodeSlot::Present(DoubleQuoteNode(node))
                                    }
                                    TerminalPlaced::Missing(node, ()) => {
                                        NodeSlot::Missing(KindMissing(DoubleQuoteNode(node)))
                                    }
                                    TerminalPlaced::Error(node) => NodeSlot::Error(node),
                                },
                                None => NodeSlot::Absent(NoChild),
                            };
                            Positioned::new(leading_extras, slot)
                        };
                        MediaFilenameDoubleQuoteChildren {
                            child_0,
                            child_1,
                            child_2,
                            trailing_extras: Vec::new(),
                            unexpected: Vec::new(),
                        }
                    }),
                    ChoicePick264::A1 => MediaFilenameChoice::RNTRNRNT(LeafText(__raw)),
                }),
                ChoicePlaced::Missing(node) => NodeSlot::Missing(node),
                ChoicePlaced::Error(node) => NodeSlot::Error(node),
            },
            None => NodeSlot::Absent(NoChild),
        };
        Positioned::new(leading_extras, slot)
    };
    let Leftovers {
        trailing_extras,
        unexpected,
    } = __cur.finish();
    MediaFilenameChildren {
        content,
        trailing_extras,
        unexpected,
    }
}
