/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_non_colon_separator<'tree>(
    node: NonColonSeparatorNode<'tree>,
) -> NonColonSeparatorChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    let content = {
        let (leading_extras, __placed) = __cur.fixed(
            ChoiceAt {
                shape: &SHAPE_325,
                select: choice_325,
            },
            &Cont::NIL,
        );
        let slot = match __placed {
            Some(__placed) => match __placed {
                ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                    ChoicePick325::A0(node) => NonColonSeparatorChoice::Comma(CommaNode(node)),
                    ChoicePick325::A1(node) => {
                        NonColonSeparatorChoice::Semicolon(SemicolonNode(node))
                    }
                    ChoicePick325::A2(node) => {
                        NonColonSeparatorChoice::TagMarker(TagMarkerNode(node))
                    }
                    ChoicePick325::A3(node) => {
                        NonColonSeparatorChoice::VocativeMarker(VocativeMarkerNode(node))
                    }
                    ChoicePick325::A4(node) => NonColonSeparatorChoice::CaContinuationMarker(
                        CaContinuationMarkerNode(node),
                    ),
                    ChoicePick325::A5(node) => {
                        NonColonSeparatorChoice::UnmarkedEnding(UnmarkedEndingNode(node))
                    }
                    ChoicePick325::A6(node) => {
                        NonColonSeparatorChoice::UptakeSymbol(UptakeSymbolNode(node))
                    }
                    ChoicePick325::A7(node) => {
                        NonColonSeparatorChoice::CaNoBreak(CaNoBreakNode(node))
                    }
                    ChoicePick325::A8(node) => {
                        NonColonSeparatorChoice::CaTechnicalBreak(CaTechnicalBreakNode(node))
                    }
                    ChoicePick325::A9(node) => {
                        NonColonSeparatorChoice::RisingToHigh(RisingToHighNode(node))
                    }
                    ChoicePick325::A10(node) => {
                        NonColonSeparatorChoice::RisingToMid(RisingToMidNode(node))
                    }
                    ChoicePick325::A11(node) => {
                        NonColonSeparatorChoice::LevelPitch(LevelPitchNode(node))
                    }
                    ChoicePick325::A12(node) => {
                        NonColonSeparatorChoice::FallingToMid(FallingToMidNode(node))
                    }
                    ChoicePick325::A13(node) => {
                        NonColonSeparatorChoice::FallingToLow(FallingToLowNode(node))
                    }
                }),
                ChoicePlaced::Missing(node) => NodeSlot::Missing(node),
                ChoicePlaced::Error(node) => NodeSlot::Error(node),
            },
            None => NodeSlot::Absent(NoChild),
        };
        Positioned::new(leading_extras, slot)
    };
    let Leftovers {
        trailing_extras,
        unexpected,
    } = __cur.finish();
    NonColonSeparatorChildren {
        content,
        trailing_extras,
        unexpected,
    }
}
impl<'tree> Extract<'tree> for NonColonSeparatorNode<'tree> {
    type Children<K: KindProof> = NonColonSeparatorChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<NonColonSeparatorChildren<'tree>, K::Refusal> {
        K::admit(evidence, self.0).map(|__raw| extract_non_colon_separator(Self(__raw)))
    }
    fn extract_broad(self) -> NonColonSeparatorChildren<'tree> {
        extract_non_colon_separator(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<NonColonSeparatorChildren<'tree>, AdmittedRefusal> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing
    /// source identity; a non-ERROR input returns `None`.
    #[must_use]
    pub fn extract_non_colon_separator_from_error_recovery(
        self,
    ) -> Option<SourceChildren<'tree, 'source, NonColonSeparatorChildren<'tree>>> {
        into_ok(self.recover_as::<NonColonSeparatorNode<'tree>, Broad>(NonColonSeparatorNode, &()))
    }
    /// The same reconstruction under the admitted kind proof.
    /// # Errors
    /// The admitted proof's refusal; a non-ERROR input returns `Ok(None)`.
    pub fn extract_non_colon_separator_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, NonColonSeparatorChildren<'tree>>>,
        AdmittedRefusal,
    > {
        self.recover_as::<NonColonSeparatorNode<'tree>, KindAdmitted>(
            NonColonSeparatorNode,
            grammar,
        )
    }
}
/// `non_colon_separator`'s children from the ERROR standing in for one; see the module header.
#[must_use]
pub fn extract_non_colon_separator_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Option<NonColonSeparatorChildren<'tree>> {
    node.is_error()
        .then(|| extract_non_colon_separator(NonColonSeparatorNode(node)))
}

