/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_number_option<'tree>(node: NumberOptionNode<'tree>) -> NumberOptionChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    let content = {
        let (leading_extras, __placed) = __cur.fixed(
            ChoiceAt {
                shape: &SHAPE_352,
                select: choice_352,
            },
            &Cont::NIL,
        );
        let slot = match __placed {
            Some(__placed) => match __placed {
                ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                    ChoicePick352::A0(node) => NumberOptionChoice::_1(K1Node(node)),
                    ChoicePick352::A1(node) => NumberOptionChoice::_2(K2Node(node)),
                    ChoicePick352::A2(node) => NumberOptionChoice::_3(K3Node(node)),
                    ChoicePick352::A3(node) => NumberOptionChoice::_4(K4Node(node)),
                    ChoicePick352::A4(node) => NumberOptionChoice::_5(K5Node(node)),
                    ChoicePick352::A5(node) => NumberOptionChoice::More(MoreNode(node)),
                    ChoicePick352::A6(node) => NumberOptionChoice::Audience(AudienceNode(node)),
                    ChoicePick352::A7(node) => {
                        NumberOptionChoice::GenericNumber(GenericNumberNode(node))
                    }
                }),
                ChoicePlaced::Missing(node) => NodeSlot::Missing(node),
                ChoicePlaced::Error(node) => NodeSlot::Error(node),
            },
            None => NodeSlot::Absent(NoChild),
        };
        Positioned::new(leading_extras, slot)
    };
    let Leftovers {
        trailing_extras,
        unexpected,
    } = __cur.finish();
    NumberOptionChildren {
        content,
        trailing_extras,
        unexpected,
    }
}
impl<'tree> Extract<'tree> for NumberOptionNode<'tree> {
    type Children<K: KindProof> = NumberOptionChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<NumberOptionChildren<'tree>, K::Refusal> {
        K::admit(evidence, self.0).map(|__raw| extract_number_option(Self(__raw)))
    }
    fn extract_broad(self) -> NumberOptionChildren<'tree> {
        extract_number_option(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<NumberOptionChildren<'tree>, AdmittedRefusal> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
