/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_participant<'tree>(node: ParticipantNode<'tree>) -> ParticipantChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    {
        let code = {
            let (leading_extras, __placed) = __cur.fixed(Terminal::of(&SHAPE_49), &Cont::NIL);
            let slot = match __placed {
                Some(__placed) => match __placed {
                    TerminalPlaced::Present(node, ()) => NodeSlot::Present(SpeakerNode(node)),
                    TerminalPlaced::Missing(node, ()) => {
                        NodeSlot::Missing(KindMissing(SpeakerNode(node)))
                    }
                    TerminalPlaced::Error(node) => NodeSlot::Error(node),
                },
                None => NodeSlot::Absent(NoChild),
            };
            Positioned::new(leading_extras, slot)
        };
        let child_1 = {
            let __c0 = __cur.tail(&SHAPES_48);
            let (leading_extras, mut __walk) = __cur.repeat(&SHAPE_377, &__c0);
            let mut __items = Vec::with_capacity(__walk.capacity());
            while let Some((leading_extras, __placed, __c1)) =
                __walk.next(&mut __cur, Sequence(&SHAPE_376))
            {
                __items.push(Positioned::new(
                    leading_extras,
                    match __placed {
                        SequencePlaced::Value => NodeSlot::Present({
                            let child_0 = {
                                let (leading_extras, __placed) =
                                    __cur.fixed(Terminal::of(&SHAPE_22), &Cont::NIL);
                                let slot = match __placed {
                                    Some(__placed) => match __placed {
                                        TerminalPlaced::Present(node, ()) => {
                                            NodeSlot::Present(WhitespacesNode(node))
                                        }
                                        TerminalPlaced::Missing(node, ()) => {
                                            NodeSlot::Missing(KindMissing(WhitespacesNode(node)))
                                        }
                                        TerminalPlaced::Error(node) => NodeSlot::Error(node),
                                    },
                                    None => NodeSlot::Absent(NoChild),
                                };
                                Positioned::new(leading_extras, slot)
                            };
                            let child_1 = {
                                let (leading_extras, __placed) =
                                    __cur.fixed(Terminal::of(&SHAPE_374), &Cont::NIL);
                                let slot = match __placed {
                                    Some(__placed) => match __placed {
                                        TerminalPlaced::Present(node, ()) => {
                                            NodeSlot::Present(ParticipantWordNode(node))
                                        }
                                        TerminalPlaced::Missing(node, ()) => NodeSlot::Missing(
                                            KindMissing(ParticipantWordNode(node)),
                                        ),
                                        TerminalPlaced::Error(node) => NodeSlot::Error(node),
                                    },
                                    None => NodeSlot::Absent(NoChild),
                                };
                                Positioned::new(leading_extras, slot)
                            };
                            ParticipantChild1Children {
                                child_0,
                                child_1,
                                trailing_extras: Vec::new(),
                                unexpected: Vec::new(),
                            }
                        }),
                        SequencePlaced::Error(node) => NodeSlot::Error(node),
                    },
                ));
            }
            Positioned::new(leading_extras, __items)
        };
        let child_2 = {
            let (leading_extras, __placed) = __cur.optional(Terminal::of(&SHAPE_22), &Cont::NIL);
            let slot = match __placed {
                Some(__placed) => Some(match __placed {
                    TerminalPlaced::Present(node, ()) => NodeSlot::Present(WhitespacesNode(node)),
                    TerminalPlaced::Missing(node, ()) => {
                        NodeSlot::Missing(KindMissing(WhitespacesNode(node)))
                    }
                    TerminalPlaced::Error(node) => NodeSlot::Error(node),
                }),
                None => None,
            };
            Positioned::new(leading_extras, slot)
        };
        let Leftovers {
            trailing_extras,
            unexpected,
        } = __cur.finish();
        ParticipantChildren {
            code,
            child_1,
            child_2,
            trailing_extras,
            unexpected,
        }
    }
}
