/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_pid_header<'tree>(node: PidHeaderNode<'tree>) -> PidHeaderChildren<'tree> {
    into_ok(node.extract_as::<Broad>(&()))
}
impl<'tree> Extract<'tree> for PidHeaderNode<'tree> {
    type Children<K: KindProof> = PidHeaderChildren<'tree, K>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<PidHeaderChildren<'tree, K>, K::Refusal> {
        let __raw = K::admit(evidence, self.0)?;
        Ok({
            let __children = collect_children(__raw);
            let mut __cur = Cursor::new(&__children);
            {
                let child_0 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_413), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(PidPrefixNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(KindMissing(PidPrefixNode(node)))
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_1 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_8), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(HeaderSepNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(K::missing(KindMissing(HeaderSepNode(node)))?)
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_2 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_10), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(FreeTextNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(K::missing(KindMissing(FreeTextNode(node)))?)
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_3 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_5), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(NewlineNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(KindMissing(NewlineNode(node)))
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let Leftovers {
                    trailing_extras,
                    unexpected,
                } = __cur.finish();
                PidHeaderChildren {
                    child_0,
                    child_1,
                    child_2,
                    child_3,
                    trailing_extras,
                    unexpected,
                }
            }
        })
    }
    fn extract_broad(self) -> PidHeaderChildren<'tree> {
        extract_pid_header(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<PidHeaderChildren<'tree, KindAdmitted>, AdmittedRefusal> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
