/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_quotation<'tree>(node: QuotationNode<'tree>) -> QuotationChildren<'tree> {
    into_ok(node.extract_as::<Broad>(&()))
}
impl<'tree> Extract<'tree> for QuotationNode<'tree> {
    type Children<K: KindProof> = QuotationChildren<'tree, K>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<QuotationChildren<'tree, K>, K::Refusal> {
        let __raw = K::admit(evidence, self.0)?;
        Ok({
            let __children = collect_children(__raw);
            let mut __cur = Cursor::new(&__children);
            {
                let child_0 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_417), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(LeftDoubleQuoteNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(KindMissing(LeftDoubleQuoteNode(node)))
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_1 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_150), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(ContentsNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(K::missing(KindMissing(ContentsNode(node)))?)
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_2 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_415), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(RightDoubleQuoteNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(KindMissing(RightDoubleQuoteNode(node)))
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let Leftovers {
                    trailing_extras,
                    unexpected,
                } = __cur.finish();
                QuotationChildren {
                    child_0,
                    child_1,
                    child_2,
                    trailing_extras,
                    unexpected,
                }
            }
        })
    }
    fn extract_broad(self) -> QuotationChildren<'tree> {
        extract_quotation(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<QuotationChildren<'tree, KindAdmitted>, AdmittedRefusal> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
