impl<'tree> Extract<'tree> for SourceFileNode<'tree> {
    type Children<K: KindProof> = SourceFileChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<SourceFileChildren<'tree>, K::Refusal> {
        K::admit(evidence, self.0).map(|__raw| extract_source_file(Self(__raw)))
    }
    fn extract_broad(self) -> SourceFileChildren<'tree> {
        extract_source_file(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<SourceFileChildren<'tree>, AdmittedRefusal> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing
    /// source identity; a non-ERROR input returns `None`.
    #[must_use]
    pub fn extract_source_file_from_error_recovery(
        self,
    ) -> Option<SourceChildren<'tree, 'source, SourceFileChildren<'tree>>> {
        into_ok(self.recover_as::<SourceFileNode<'tree>, Broad>(SourceFileNode, &()))
    }
    /// The same reconstruction under the admitted kind proof.
    /// # Errors
    /// The admitted proof's refusal; a non-ERROR input returns `Ok(None)`.
    pub fn extract_source_file_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<Option<SourceChildren<'tree, 'source, SourceFileChildren<'tree>>>, AdmittedRefusal>
    {
        self.recover_as::<SourceFileNode<'tree>, KindAdmitted>(SourceFileNode, grammar)
    }
}
/// `source_file`'s children from the ERROR standing in for one; see the module header.
#[must_use]
pub fn extract_source_file_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Option<SourceFileChildren<'tree>> {
    node.is_error()
        .then(|| extract_source_file(SourceFileNode(node)))
}

