/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_spa_dependent_tier<'tree>(
    node: SpaDependentTierNode<'tree>,
) -> SpaDependentTierChildren<'tree> {
    into_ok(node.extract_as::<Broad>(&()))
}
impl<'tree> Extract<'tree> for SpaDependentTierNode<'tree> {
    type Children<K: KindProof> = SpaDependentTierChildren<'tree, K>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<SpaDependentTierChildren<'tree, K>, K::Refusal> {
        let __raw = K::admit(evidence, self.0)?;
        Ok({
            let __children = collect_children(__raw);
            let mut __cur = Cursor::new(&__children);
            {
                let child_0 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_461), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(SpaTierPrefixNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(KindMissing(SpaTierPrefixNode(node)))
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_1 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_0), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(TierSepNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(K::missing(KindMissing(TierSepNode(node)))?)
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_2 = {
                    let __c0 = __cur.tail(&SHAPES_0);
                    let (leading_extras, __placed) = __cur.optional(Terminal::of(&SHAPE_2), &__c0);
                    let slot = match __placed {
                        Some(__placed) => Some(match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(TextWithBulletsNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => NodeSlot::Missing(K::missing(
                                KindMissing(TextWithBulletsNode(node)),
                            )?),
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        }),
                        None => None,
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_3 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_5), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(NewlineNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(KindMissing(NewlineNode(node)))
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let Leftovers {
                    trailing_extras,
                    unexpected,
                } = __cur.finish();
                SpaDependentTierChildren {
                    child_0,
                    child_1,
                    child_2,
                    child_3,
                    trailing_extras,
                    unexpected,
                }
            }
        })
    }
    fn extract_broad(self) -> SpaDependentTierChildren<'tree> {
        extract_spa_dependent_tier(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<SpaDependentTierChildren<'tree, KindAdmitted>, AdmittedRefusal> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
