/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_transcription_header<'tree>(
    node: TranscriptionHeaderNode<'tree>,
) -> TranscriptionHeaderChildren<'tree> {
    into_ok(node.extract_as::<Broad>(&()))
}
impl<'tree> Extract<'tree> for TranscriptionHeaderNode<'tree> {
    type Children<K: KindProof> = TranscriptionHeaderChildren<'tree, K>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<TranscriptionHeaderChildren<'tree, K>, K::Refusal> {
        let __raw = K::admit(evidence, self.0)?;
        Ok({
            let __children = collect_children(__raw);
            let mut __cur = Cursor::new(&__children);
            {
                let child_0 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_513), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(TranscriptionPrefixNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(KindMissing(TranscriptionPrefixNode(node)))
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_1 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_8), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(HeaderSepNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(K::missing(KindMissing(HeaderSepNode(node)))?)
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_2 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_511), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(TranscriptionOptionNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => NodeSlot::Missing(K::missing(
                                KindMissing(TranscriptionOptionNode(node)),
                            )?),
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let child_3 = {
                    let (leading_extras, __placed) =
                        __cur.fixed(Terminal::of(&SHAPE_5), &Cont::NIL);
                    let slot = match __placed {
                        Some(__placed) => match __placed {
                            TerminalPlaced::Present(node, ()) => {
                                NodeSlot::Present(NewlineNode(node))
                            }
                            TerminalPlaced::Missing(node, ()) => {
                                NodeSlot::Missing(KindMissing(NewlineNode(node)))
                            }
                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                        },
                        None => NodeSlot::Absent(NoChild),
                    };
                    Positioned::new(leading_extras, slot)
                };
                let Leftovers {
                    trailing_extras,
                    unexpected,
                } = __cur.finish();
                TranscriptionHeaderChildren {
                    child_0,
                    child_1,
                    child_2,
                    child_3,
                    trailing_extras,
                    unexpected,
                }
            }
        })
    }
    fn extract_broad(self) -> TranscriptionHeaderChildren<'tree> {
        extract_transcription_header(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<TranscriptionHeaderChildren<'tree, KindAdmitted>, AdmittedRefusal> {
        self.extract_as::<KindAdmitted>(grammar)
    }
}
impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing
    /// source identity; a non-ERROR input returns `None`.
    #[must_use]
    pub fn extract_transcription_header_from_error_recovery(
        self,
    ) -> Option<SourceChildren<'tree, 'source, TranscriptionHeaderChildren<'tree>>> {
        into_ok(
            self.recover_as::<TranscriptionHeaderNode<'tree>, Broad>(TranscriptionHeaderNode, &()),
        )
    }
    /// The same reconstruction under the admitted kind proof.
    /// # Errors
    /// The admitted proof's refusal; a non-ERROR input returns `Ok(None)`.
    pub fn extract_transcription_header_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, TranscriptionHeaderChildren<'tree, KindAdmitted>>>,
        AdmittedRefusal,
    > {
        self.recover_as::<TranscriptionHeaderNode<'tree>, KindAdmitted>(
            TranscriptionHeaderNode,
            grammar,
        )
    }
}
/// `transcription_header`'s children from the ERROR standing in for one; see the module header.
#[must_use]
pub fn extract_transcription_header_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Option<TranscriptionHeaderChildren<'tree>> {
    node.is_error()
        .then(|| extract_transcription_header(TranscriptionHeaderNode(node)))
}

// Task 7 extract contract: pub fn extract_transcription_option<'tree>(node: TranscriptionOptionNode<'tree>) -> TranscriptionOptionChildren<'tree>
pub enum TranscriptionOptionChoice<'tree, R: RangePhase<'tree> = Raw> {
    /// Alternative `EyeDialect`.
    EyeDialect(R::Wrapper<EyeDialectNode<'tree>>),
    /// Alternative `Partial`.
    Partial(R::Wrapper<PartialNode<'tree>>),
    /// Alternative `Full`.
    Full(R::Wrapper<FullNode<'tree>>),
    /// Alternative `Detailed`.
    Detailed(R::Wrapper<DetailedNode<'tree>>),
    /// Alternative `Coarse`.
    Coarse(R::Wrapper<CoarseNode<'tree>>),
    /// Alternative `Checked`.
    Checked(R::Wrapper<CheckedNode<'tree>>),
    /// Alternative `Anonymized`.
    Anonymized(R::Wrapper<AnonymizedNode<'tree>>),
    /// Alternative `GenericTranscription`.
    GenericTranscription(R::Wrapper<GenericTranscriptionNode<'tree>>),
}
impl<'tree, R: RangePhase<'tree>> std::fmt::Debug for TranscriptionOptionChoice<'tree, R>
where
    R::Wrapper<EyeDialectNode<'tree>>: std::fmt::Debug,
    R::Wrapper<PartialNode<'tree>>: std::fmt::Debug,
    R::Wrapper<FullNode<'tree>>: std::fmt::Debug,
    R::Wrapper<DetailedNode<'tree>>: std::fmt::Debug,
    R::Wrapper<CoarseNode<'tree>>: std::fmt::Debug,
    R::Wrapper<CheckedNode<'tree>>: std::fmt::Debug,
    R::Wrapper<AnonymizedNode<'tree>>: std::fmt::Debug,
    R::Wrapper<GenericTranscriptionNode<'tree>>: std::fmt::Debug,
{
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::EyeDialect(value) => f.debug_tuple("EyeDialect").field(value).finish(),
            Self::Partial(value) => f.debug_tuple("Partial").field(value).finish(),
            Self::Full(value) => f.debug_tuple("Full").field(value).finish(),
            Self::Detailed(value) => f.debug_tuple("Detailed").field(value).finish(),
            Self::Coarse(value) => f.debug_tuple("Coarse").field(value).finish(),
            Self::Checked(value) => f.debug_tuple("Checked").field(value).finish(),
            Self::Anonymized(value) => f.debug_tuple("Anonymized").field(value).finish(),
            Self::GenericTranscription(value) => {
                f.debug_tuple("GenericTranscription").field(value).finish()
            }
        }
    }
}
