/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_transcription_option<'tree>(
    node: TranscriptionOptionNode<'tree>,
) -> TranscriptionOptionChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children);
    let content = {
        let (leading_extras, __placed) = __cur.fixed(
            ChoiceAt {
                shape: &SHAPE_522,
                select: choice_522,
            },
            &Cont::NIL,
        );
        let slot = match __placed {
            Some(__placed) => match __placed {
                ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                    ChoicePick522::A0(node) => {
                        TranscriptionOptionChoice::EyeDialect(EyeDialectNode(node))
                    }
                    ChoicePick522::A1(node) => {
                        TranscriptionOptionChoice::Partial(PartialNode(node))
                    }
                    ChoicePick522::A2(node) => TranscriptionOptionChoice::Full(FullNode(node)),
                    ChoicePick522::A3(node) => {
                        TranscriptionOptionChoice::Detailed(DetailedNode(node))
                    }
                    ChoicePick522::A4(node) => TranscriptionOptionChoice::Coarse(CoarseNode(node)),
                    ChoicePick522::A5(node) => {
                        TranscriptionOptionChoice::Checked(CheckedNode(node))
                    }
                    ChoicePick522::A6(node) => {
                        TranscriptionOptionChoice::Anonymized(AnonymizedNode(node))
                    }
                    ChoicePick522::A7(node) => TranscriptionOptionChoice::GenericTranscription(
                        GenericTranscriptionNode(node),
                    ),
                }),
                ChoicePlaced::Missing(node) => NodeSlot::Missing(node),
                ChoicePlaced::Error(node) => NodeSlot::Error(node),
            },
            None => NodeSlot::Absent(NoChild),
        };
        Positioned::new(leading_extras, slot)
    };
    let Leftovers {
        trailing_extras,
        unexpected,
    } = __cur.finish();
    TranscriptionOptionChildren {
        content,
        trailing_extras,
        unexpected,
    }
}
