    pub fn extract_xphoint_dependent_tier_from_error_recovery(
        self,
    ) -> Option<SourceChildren<'tree, 'source, XphointDependentTierChildren<'tree>>> {
        into_ok(
            self.recover_as::<XphointDependentTierNode<'tree>, Broad>(
                XphointDependentTierNode,
                &(),
            ),
        )
    }
    /// The same reconstruction under the admitted kind proof.
